constraints:
1 ≤ N ≤ 10^{5}

expected time complexity: O(N)
expected auxiliary space: O(N)

standard_solution_code:
class Solution:

	def minLength(self, s, n):
		stack = []
		stack.append(int(s[0]))
		for ch in s[1:]:
			if stack and (int(ch) == 0 and stack[-1] == 9 or (int(ch) == 9 and stack[-1] == 0) or (int(ch) - stack[-1] == 1 and int(ch) % 2 == 0) or (stack[-1] - int(ch) == 1 and stack[-1] % 2 == 0)):
				stack.pop()
			else:
				stack.append(int(ch))
		return len(stack)
